import Dexie from "dexie";

export const db = new Dexie("FlashCardDB");

db.version(1).stores({
  decks: "++id, name, progress, updatedAt",
  cards: "++id, deckId, word, level, createdAt, updatedAt",
  syncQueue: "++id, type, targetId, payload, status, createdAt"
});

// Helper to get now timestamp
const now = () => new Date().toISOString();

// Decks
export const addDeck = async (deck) => {
  const toAdd = {
    name: deck.name || "Untitled",
    progress: deck.progress || 0,
    updatedAt: now(),
  };
  const id = await db.decks.add(toAdd);
  return { id, ...toAdd };
};

export const getDecks = async () => {
  return await db.decks.toArray();
};

export const getDeck = async (id) => {
  return await db.decks.get(Number(id));
};

export const updateDeck = async (id, updates) => {
  updates.updatedAt = now();
  await db.decks.update(Number(id), updates);
  return await getDeck(id);
};

export const deleteDeck = async (id) => {
  return await db.decks.delete(Number(id));
};

// Cards
export const addCard = async (card) => {
  const toAdd = {
    deckId: Number(card.deckId),
    word: card.word || "",
    phonetic: card.phonetic || "",
    audio: card.audio || "",
    synonyms: card.synonyms || [],
    meaning_en: card.meaning_en || "",
    example: card.example || "",
    note: card.note || "",
    level: card.level || 0,
    createdAt: now(),
    updatedAt: now(),
  };
  const id = await db.cards.add(toAdd);
  return { id, ...toAdd };
};

export const getCard = async (id) => {
  return await db.cards.get(Number(id));
};

export const getCardsByDeck = async (deckId) => {
  return await db.cards.where("deckId").equals(Number(deckId)).toArray();
};

export const updateCard = async (id, updates) => {
  updates.updatedAt = now();
  await db.cards.update(Number(id), updates);
  return await getCard(id);
};

export const deleteCard = async (id) => {
  return await db.cards.delete(Number(id));
};

// Bulk import/export and clearing
export const exportAll = async () => {
  const decks = await getDecks();
  const cards = await db.cards.toArray();
  return { decks, cards, exportedAt: now() };
};

export const importAll = async (payload) => {
  if (!payload) return;
  if (payload.decks && payload.decks.length) {
    await db.transaction("rw", db.decks, db.cards, async () => {
      await db.decks.clear();
      await db.cards.clear();
      for (const d of payload.decks) {
        const { id, ...rest } = d;
        await db.decks.add(rest);
      }
      for (const c of payload.cards) {
        const { id, ...rest } = c;
        await db.cards.add(rest);
      }
    });
  }
};

export const clearAll = async () => {
  await db.transaction("rw", db.decks, db.cards, async () => {
    await db.decks.clear();
    await db.cards.clear();
  });
};

// Utility: ensure DB open
export const openDB = async () => {
  await db.open();
  return db;
};

export default db;



// SYNC QUEUE: queue local changes to be sent to server when online
export const queueChange = async ({ type, targetId = null, payload = {} }) => {
  const entry = {
    type, // e.g., "addCard","updateCard","deleteCard","addDeck",...
    targetId: targetId ? Number(targetId) : null,
    payload,
    status: "pending",
    createdAt: new Date().toISOString(),
  };
  const id = await db.syncQueue.add(entry);
  return { id, ...entry };
};

// get pending queue entries
export const getPendingQueue = async () => {
  return await db.syncQueue.where('status').equals('pending').toArray();
};

// mark queue entry as done
export const markQueueDone = async (id) => {
  await db.syncQueue.update(Number(id), { status: 'done', updatedAt: new Date().toISOString() });
};

// naive sync function: try to send queued changes to server endpoint /api/sync
export const processQueue = async () => {
  if (!navigator.onLine) return { ok: false, reason: 'offline' };
  const pending = await getPendingQueue();
  if (!pending.length) return { ok: true, processed: 0 };

  let processed = 0;
  for (const item of pending) {
    try {
      // NOTE: replace /api/sync with your real server endpoint
      const res = await fetch('/api/sync', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(item),
      });
      if (res.ok) {
        await markQueueDone(item.id);
        processed++;
      } else {
        // if server responded with error, stop or mark as failed
        console.warn('Sync failed for item', item.id, res.status);
      }
    } catch (err) {
      console.warn('Network error during sync for item', item.id, err);
      // stop processing if network error
      return { ok: false, reason: 'network error' };
    }
  }
  return { ok: true, processed };
};

// helper: when performing local operations, queue them for later sync
// Example wrappers for addCard/updateCard/deleteCard to queue changes automatically
export const addCardAndQueue = async (card) => {
  const added = await addCard(card);
  try {
    await queueChange({ type: 'addCard', targetId: added.id, payload: added });
  } catch (e) {
    console.warn('queueing failed', e);
  }
  return added;
};

export const updateCardAndQueue = async (id, updates) => {
  const updated = await updateCard(id, updates);
  try {
    await queueChange({ type: 'updateCard', targetId: id, payload: updates });
  } catch (e) {
    console.warn('queueing failed', e);
  }
  return updated;
};

export const deleteCardAndQueue = async (id) => {
  await deleteCard(id);
  try {
    await queueChange({ type: 'deleteCard', targetId: id, payload: {} });
  } catch (e) {
    console.warn('queueing failed', e);
  }
  return true;
};

