import React, { useEffect, useState } from "react";
import { useParams, useLocation, useNavigate } from "react-router-dom";
import { Container, Button } from "react-bootstrap";
import { Swiper, SwiperSlide } from "swiper/react";
import { EffectCards } from "swiper/modules";
import "swiper/css";
import "swiper/css/effect-cards";
import { getCardsByDeck, db } from "../db";
import FlashCardModal from "../components/modals/FlashCardModal";
import ConfirmDeleteModal from "../components/modals/ConfirmDeleteModal";
import EditFlashCardModal from "../components/modals/EditFlashCardModal"; 

import "./DeckPage.css";

export default function DeckPageSwiper() {
  const { id } = useParams();
  const isAll = id === "all";
  const { state } = useLocation();
  const navigate = useNavigate();
  const deckId = isAll ? null : Number(id);
  const deckName = isAll
    ? "Total Cards"
    : state?.deck?.name || `Deck ${deckId}`;

  const [cards, setCards] = useState([]);
  const [flipped, setFlipped] = useState({});
  const [theme, setTheme] = useState("dark");
  const [currentIndex, setCurrentIndex] = useState(1);
  // 🔹 state برای Modal کارت Mastered
  const [showMasteredModal, setShowMasteredModal] = useState(false);

  // ---------- Modal ویرایش ----------
  const [showEditModal, setShowEditModal] = useState(false);
  const [currentEditCard, setCurrentEditCard] = useState(null);

  // ---------- Modal حذف ----------
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [cardToDelete, setCardToDelete] = useState(null);

  useEffect(() => {
    const loadCards = async () => {
      if (isNaN(deckId)) return;
      const deckCards = await getCardsByDeck(deckId);
      setCards(deckCards);
    };
    loadCards();
  }, [deckId]);

  useEffect(() => {
    const loadCards = async () => {
      if (isAll) {
        const all = await db.cards.toArray();
        setCards(all);
      } else {
        if (isNaN(deckId)) return;
        const deckCards = await getCardsByDeck(deckId);
        setCards(deckCards);
      }
    };
    loadCards();
  }, [id]); // ← به id وابسته باشد تا با رفتن به /deck/all ری‌لود شود

  const toggleFlip = (cardId) => {
    setFlipped((prev) => ({
      ...prev,
      [cardId]: !prev[cardId],
    }));
  };

  const speakWord = (word) => {
    const utterance = new SpeechSynthesisUtterance(word);
    utterance.lang = "en-US";
    speechSynthesis.speak(utterance);
  };

  // ---------- باز کردن Modal ویرایش ----------
  const handleEditCard = (card) => {
    setCurrentEditCard(card);
    setShowEditModal(true);
  };

  // ---------- ذخیره تغییرات کارت ----------
  const handleSaveEditCard = async () => {
    if (!currentEditCard) return;

    await db.cards.put(currentEditCard); // بروز رسانی در Dexie

    const updatedCards = await getCardsByDeck(deckId);
    setCards(updatedCards);

    setShowEditModal(false);
    setCurrentEditCard(null);
  };

  const handleDeleteCard = (card) => {
    setCardToDelete(card);
    setShowDeleteModal(true);
  };

  const confirmDeleteCard = async () => {
    if (!cardToDelete) return;

    await db.cards.delete(cardToDelete.id);

    // آپدیت تعداد کارت‌های deck
    const deck = await db.decks.get(cardToDelete.deckId);
    if (deck) {
      const deckCards = await db.cards
        .where("deckId")
        .equals(deck.id)
        .toArray();
      deck.cards = deckCards.length;
      await db.decks.put(deck);
    }

    // بارگذاری مجدد کارت‌ها متناسب با حالت صفحه
    if (isAll) {
      const all = await db.cards.toArray();
      setCards(all);
    } else {
      const updatedCards = await getCardsByDeck(deckId);
      setCards(updatedCards);
    }

    // const updatedCards = await getCardsByDeck(deckId);
    // setCards(updatedCards);
    setShowDeleteModal(false);
    setCardToDelete(null);
  };

  const handleChangeLevel = async (card) => {
    const newLevel = ((card.level || 1) % 6) + 1; // افزایش 1 تا 6
    card.level = newLevel;
    await db.cards.put(card);

    setCards((prev) =>
      prev.map((c) => (c.id === card.id ? { ...c, level: newLevel } : c))
    );

    // 🔹 اگر سطح کارت به 6 رسید، Modal تبریک نمایش داده شود
    if (newLevel === 6) {
      setShowMasteredModal(true);
    }
  };

  return (
    <Container
      className={`deck-page  justify-center items-center `}
      style={{ minHeight: "100vh" }}
    >
      <div className="box-flashcard text-center">
        <div className="mb-4 text-start">
          <Button variant="primary" onClick={() => navigate("/")}>
            ⬅ Back to Home
          </Button>
        </div>

        <h2 className="mb-4">Deck: {deckName}</h2>

        <p className="text-info mb-3">
          {currentIndex} of {cards.length}
        </p>

        {cards.length === 0 ? (
          <p>No flashcards in this deck yet.</p>
        ) : (
          <Swiper
            effect={"cards"}
            grabCursor={true}
            loop={false} // ✅ کارت‌ها بی‌نهایت می‌چرخند
            modules={[EffectCards]}
            className="mySwiper"
            onSlideChange={(swiper) =>
              setCurrentIndex(
                (swiper.realIndex + 1) % cards.length || cards.length
              )
            }
          >
            {cards.map((card) => (
              <SwiperSlide key={card.id}>
                <div
                  className={`flashcard_d ${flipped[card.id] ? "flipped" : ""}`}
                >
                  <div className="flashcard-inner">
                    <div className="flashcard-front">
                      <br />

                      <h5>{card.word}</h5>
                      <p>{card.phonetic}</p>

                      <Button
                        variant="outline-light"
                        size="sm"
                        onClick={() => speakWord(card.word)}
                        className="flashcard-btn"
                      >
                        🎧 Listen
                      </Button>

                      <Button
                        variant="warning"
                        size="sm"
                        className="flashcard-btn"
                        onClick={() => handleEditCard(card)}
                      >
                        ✏️ Edit
                      </Button>
                      {/* ---------- Change Level ---------- */}
                      <Button
                        variant="info"
                        size="sm"
                        className="flashcard-btn"
                        onClick={() => handleChangeLevel(card)}
                      >
                        Change Level (Current: {card.level || 1})
                      </Button>

                      <Button
                        variant="danger"
                        size="sm"
                        className="flashcard-btn"
                        onClick={() => handleDeleteCard(card)}
                      >
                        🗑 Delete
                      </Button>

                      <br />
                      <Button
                        variant="secondary"
                        size="sm"
                        className="flashcard-btn"
                        onClick={() => toggleFlip(card.id)}
                      >
                        Flip →
                      </Button>
                      <br />
                    </div>

                    <div className="flashcard-back">
                      {card.meaning_en && (
                        <p>
                          <strong>Meaning (EN):</strong> {card.meaning_en}
                        </p>
                      )}

                      {card.meaning_fa && (
                        <p>
                          <strong>Meaning (FA):</strong> {card.meaning_fa}
                        </p>
                      )}

                      {card.example && (
                        <p>
                          <strong>Example:</strong> {card.example}
                        </p>
                      )}

                      {card.note && (
                        <p>
                          <strong>Note:</strong> {card.note}
                        </p>
                      )}

                      {card.synonyms?.length > 0 && (
                        <p>
                          <strong>Synonyms:</strong> {card.synonyms.join(", ")}
                        </p>
                      )}

                      {/* نمایش Level */}
                      <p>
                        <strong>Level:</strong> {card.level || 1}
                      </p>

                      <Button
                        variant="secondary"
                        size="sm"
                        className="flashcard-btn"
                        onClick={() => toggleFlip(card.id)}
                      >
                        ← Flip Back
                      </Button>
                    </div>
                  </div>
                </div>
              </SwiperSlide>
            ))}
          </Swiper>
        )}
      </div>

          {/* ---------- Modal ویرایش ---------- */}
      {currentEditCard && (
        <EditFlashCardModal
          show={showEditModal}
          onClose={() => setShowEditModal(false)}
          onSave={handleSaveEditCard}
          theme={theme}
          currentWordData={currentEditCard}
          setCurrentWordData={setCurrentEditCard}
        />
      )}



      {cardToDelete && (
        <ConfirmDeleteModal
          show={showDeleteModal}
          onClose={() => setShowDeleteModal(false)}
          onConfirm={confirmDeleteCard}
          theme={theme}
          deckToDelete={{ name: cardToDelete.word }}
        />
      )}
    </Container>
  );
}
