import { Modal, Button, FormControl, Form } from "react-bootstrap";

export default function AddDeckModal({
  show,
  onClose,
  onSave,
  theme,
  inputRef,
  newDeckName,
  setNewDeckName,
}) {
  return (
    <Modal show={show} onHide={onClose} centered>
      <Modal.Header
        closeButton
        className={theme === "light" ? "bg-light text-dark" : "bg-dark text-light"}
      >
        <Modal.Title>Add New Deck</Modal.Title>
      </Modal.Header>

      <Modal.Body
        className={theme === "light" ? "bg-light text-dark" : "bg-dark text-light"}
      >
        <Form>
          <FormControl
            ref={inputRef}
            type="text"
            placeholder="Enter deck name"
            value={newDeckName}
            onChange={(e) => setNewDeckName(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter") {
                e.preventDefault();
                onSave();
              }
            }}
            className={
              theme === "light"
                ? "bg-white text-dark"
                : "bg-secondary text-light"
            }
          />
        </Form>
      </Modal.Body>

      <Modal.Footer
        className={theme === "light" ? "bg-light text-dark" : "bg-dark text-light"}
      >
        <Button variant="secondary" onClick={onClose}>
          Cancel
        </Button>
        <Button variant="primary" onClick={onSave}>
          Save
        </Button>
      </Modal.Footer>
    </Modal>
  );
}
