import React, { useState, useEffect } from "react";
import { Form, FormControl, ListGroup, Placeholder } from "react-bootstrap";

export default function WordSearch({ onSelectWord, theme }) {
  const [query, setQuery] = useState("");
  const [suggestions, setSuggestions] = useState([]);

  useEffect(() => {
    if (query.length < 2) {
      setSuggestions([]);
      return;
    }

    const fetchSuggestions = async () => {
      try {
        const res = await fetch(`https://api.datamuse.com/sug?s=${query}`);
        const data = await res.json();
        setSuggestions(data);
      } catch (err) {
        console.error(err);
      }
    };

    fetchSuggestions();
  }, [query]);

  return (
    <div style={{ position: "relative" }} className="mb-3">

      <style>
        {`
          input.dark-placeholder::placeholder {
            color: #aaa;
            opacity: 1;
          }
        `}
      </style>
  
      <Form>
        <FormControl
          type="text"
          placeholder="Search or add a new word..."
          value={query}
            onChange={(e) => setQuery(e.target.value)}
         onKeyDown={(e) => {
    if (e.key === "Enter") {
      e.preventDefault(); // جلوگیری از submit فرم
      if (query.trim() !== "") {
        onSelectWord(query.trim());
        setQuery("");
        setSuggestions([]);
      }
    }
    }}
    className={theme === "dark" ? "bg-dark text-light border-light dark-placeholder" : ""}
        />
      </Form>

      {suggestions.length > 0 && (
        <ListGroup
          style={{ position: "absolute", zIndex: 10, width: "100%" }}
          className={theme === "dark" ? "bg-dark text-light" : ""}
        >
          {suggestions.map((s, i) => (
            <ListGroup.Item
              key={i}
              action
              onClick={() => {
                onSelectWord(s.word);
                setQuery("");
                setSuggestions([]);
              }}
              className={theme === "dark" ? "bg-dark text-light border-light" : ""}
            >
              {s.word}
            </ListGroup.Item>
          ))}
        </ListGroup>
      )}
    </div>
  );
}
