import { Modal, Button, Form } from "react-bootstrap";

export default function FlashCardModal({
  show,
  onClose,
  onSave,
  theme,
  currentWordData,
  setCurrentWordData,
  decks,
  selectedDeckId,
  setSelectedDeckId,
  newDeckForFlash,
  setNewDeckForFlash,
  handleAddDeckFromFlash,
}) {
  return (
    <Modal 
  show={show} 
  onHide={onClose} 
  centered 
  size="lg"
  style={{  width: "100%" }} // 👈 اضافه شد
>
      <Modal.Header
        closeButton
        className={theme === "light" ? "bg-light text-dark" : "bg-dark text-light"}
      >
        <Modal.Title>FlashCard</Modal.Title>
      </Modal.Header>

      <Modal.Body
        className={theme === "light" ? "bg-light text-dark" : "bg-dark text-light"}
      >
        {currentWordData && (
          <Form className="d-flex flex-column gap-3">
            <Form.Group>
              <Form.Label>Word</Form.Label>
              <Form.Control
                type="text"
                value={currentWordData.word}
                onChange={(e) =>
                  setCurrentWordData({ ...currentWordData, word: e.target.value })
                }
                className={theme === "light" ? "bg-white text-dark" : "bg-secondary text-light"}
              />
            </Form.Group>

            <Form.Group>
              <Form.Label>Phonetic</Form.Label>
              <Form.Control
                type="text"
                value={currentWordData.phonetic}
                onChange={(e) =>
                  setCurrentWordData({ ...currentWordData, phonetic: e.target.value })
                }
                className={theme === "light" ? "bg-white text-dark" : "bg-secondary text-light"}
              />
            </Form.Group>

            <Form.Group>
              <Form.Label>Meaning (EN)</Form.Label>
              <Form.Control
                as="textarea"
                rows={2}
                value={currentWordData.meaning_en}
                onChange={(e) =>
                  setCurrentWordData({ ...currentWordData, meaning_en: e.target.value })
                }
                className={theme === "light" ? "bg-white text-dark" : "bg-secondary text-light"}
              />
            </Form.Group>

            <Form.Group>
              <Form.Label>Meaning (FA)</Form.Label>
              <Form.Control
                as="textarea"
                rows={2}
                value={currentWordData.meaning_fa}
                onChange={(e) =>
                  setCurrentWordData({ ...currentWordData, meaning_fa: e.target.value })
                }
                className={theme === "light" ? "bg-white text-dark" : "bg-secondary text-light"}
              />
            </Form.Group>

            <Form.Group>
              <Form.Label>Example</Form.Label>
              <Form.Control
                type="text"
                value={currentWordData.example}
                onChange={(e) =>
                  setCurrentWordData({ ...currentWordData, example: e.target.value })
                }
                className={theme === "light" ? "bg-white text-dark" : "bg-secondary text-light"}
              />
            </Form.Group>

           <Form.Group>
  <Form.Label>Synonyms (comma separated)</Form.Label>
  <Form.Control
    type="text"
    value={currentWordData.synonyms ? currentWordData.synonyms.join(", ") : ""}
    onChange={(e) =>
      setCurrentWordData({
        ...currentWordData,
        synonyms: e.target.value
          ? e.target.value.split(",").map((s) => s.trim())
          : [],
      })
    }
    className={theme === "light" ? "bg-white text-dark" : "bg-secondary text-light"}
  />
</Form.Group>


                {/* اضافه کردن یاداشت */}
            <Form.Group>
              <Form.Label>Note</Form.Label>
              <Form.Control
                as="textarea"
                rows={2}
                value={currentWordData.note}
                onChange={(e) =>
                  setCurrentWordData({ ...currentWordData, note: e.target.value })
                }
                className={theme === "light" ? "bg-white text-dark" : "bg-secondary text-light"}
              />
            </Form.Group>


            {/* انتخاب دسته */}
            <Form.Group>
              <Form.Label>Choose Deck</Form.Label>
              <Form.Select
                value={selectedDeckId}
                onChange={(e) => setSelectedDeckId(e.target.value)}
                className={theme === "light" ? "bg-white text-dark" : "bg-secondary text-light"}
              >
                {decks.map((deck) => (
                  <option key={deck.id} value={deck.id}>
                    {deck.name}
                  </option>
                ))}
              </Form.Select>
              <div className="d-flex gap-2 mt-2">
                <Form.Control
                  type="text"
                  placeholder="Add New Deck"
                  value={newDeckForFlash}
                  onChange={(e) => setNewDeckForFlash(e.target.value)}
                  className={theme === "light" ? "bg-white text-dark" : "bg-secondary text-light"}
                />
                <Button variant="success" onClick={handleAddDeckFromFlash}>
                  Add Deck
                </Button>
              </div>
            </Form.Group>
          </Form>
        )}
      </Modal.Body>

      <Modal.Footer
        className={theme === "light" ? "bg-light text-dark" : "bg-dark text-light"}
      >
        <Button variant="danger" onClick={onClose}>
          Cancel
        </Button>
        <Button variant="primary" onClick={onSave} disabled={decks.filter(deck => !deck.isVirtual).length === 0} >
          save
        </Button>
      </Modal.Footer>
    </Modal>
  );
}
