import React, { useState, useEffect } from "react";
import { Button, Modal, Form } from "react-bootstrap";
import { db, getDecks } from "../db"; // Dexie DB

export default function BackupControls({ setDecks, theme }) {
  const [showModal, setShowModal] = useState(false);
  const [importFile, setImportFile] = useState(null);
  const [resultModal, setResultModal] = useState({ show: false, success: true, message: "" });
  const [exportModal, setExportModal] = useState(false);

  const [decksList, setDecksList] = useState([]);
  const [selectedDecks, setSelectedDecks] = useState([]);

  // load decks for export modal
  useEffect(() => {
    getDecks().then(setDecksList);
  }, []);

  // ---------- Export ----------
  const handleExport = async () => {
    // if no selection => export all
    const exportIds = selectedDecks.length > 0 ? selectedDecks : decksList.map(d => d.id);

    const decks = await db.decks.where("id").anyOf(exportIds).toArray();
    const deckIds = decks.map(d => d.id);
    const cards = await db.cards.where("deckId").anyOf(deckIds).toArray();

    const data = { decks, cards };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" });
    const url = URL.createObjectURL(blob);

    const a = document.createElement("a");
    a.href = url;
    a.download = selectedDecks.length > 0 ? "flashcards_partial_backup.json" : "flashcards_backup.json";
    a.click();
    URL.revokeObjectURL(url);

    setExportModal(false);
    setSelectedDecks([]);
  };

  const toggleSelect = (id) => {
    setSelectedDecks(prev =>
      prev.includes(id) ? prev.filter(d => d !== id) : [...prev, id]
    );
  };

  // ---------- Import ----------
  const handleImportFile = (event) => {
    const file = event.target.files[0];
    if (file) {
      setImportFile(file);
      setShowModal(true);
    }
  };

  const processImport = async (replace = false) => {
    if (!importFile) return;
    const reader = new FileReader();

    reader.onload = async (e) => {
      try {
        const importedData = JSON.parse(e.target.result);

        if (replace) {
          await db.delete(); 
          await db.open();   
        }

        const deckIdMap = {}; 

        if (importedData.decks) {
          for (const deck of importedData.decks) {
            const { id, ...deckWithoutId } = deck;
            const newDeckId = await db.decks.add(deckWithoutId);
            deckIdMap[id] = newDeckId;
          }
        }

        if (importedData.cards) {
          for (const card of importedData.cards) {
            const { id, deckId, ...cardWithoutId } = card;
            const newDeckId = deckIdMap[deckId];
            if (newDeckId) {
              await db.cards.add({ ...cardWithoutId, deckId: newDeckId });
            }
          }
        }

        const updatedDecks = await getDecks();
        setDecks(updatedDecks);

        setResultModal({ show: true, success: true, message: "✅ Import completed successfully!" });
      } catch (err) {
        console.error("Failed to import:", err);
        setResultModal({ show: true, success: false, message: "❌ Invalid file!" });
      } finally {
        setShowModal(false);
        setImportFile(null);
      }
    };

    reader.readAsText(importFile);
  };

  return (
    <div className="d-flex flex-column flex-md-row gap-2 mb-4">
      {/* -------- Export Button -------- */}
      <Button
        variant={theme === "light" ? "success" : "warning"}
        onClick={() => setExportModal(true)}
      >
        💾 Export Backup
      </Button>

      {/* -------- Import Button -------- */}
      <label
        className={`btn ${theme === "light" ? "btn-primary" : "btn-warning"} mb-0`}
      >
        📂 Import Backup
        <input type="file" accept=".json" onChange={handleImportFile} hidden />
      </label>

      {/* -------- Export Options Modal -------- */}
      <Modal
        show={exportModal}
        onHide={() => setExportModal(false)}
        centered
        contentClassName={theme === "dark" ? "bg-dark text-light" : ""}
      >
        <Modal.Header closeButton closeVariant={theme === "dark" ? "white" : undefined}>
          <Modal.Title>📤 Select Decks to Export</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <p>Select which decks you want to export (leave empty to export all):</p>
          <Form>
            {decksList.map((deck) => (
              <Form.Check
                key={deck.id}
                type="checkbox"
                label={deck.name}
                checked={selectedDecks.includes(deck.id)}
                onChange={() => toggleSelect(deck.id)}
              />
            ))}
          </Form>
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setExportModal(false)}>Cancel</Button>
          <Button variant="success" onClick={handleExport}>Export</Button>
        </Modal.Footer>
      </Modal>

      {/* -------- Import Options Modal -------- */}
      <Modal 
        show={showModal} 
        onHide={() => setShowModal(false)} 
        centered
        contentClassName={theme === "dark" ? "bg-dark text-light" : ""}
      >
        <Modal.Header closeButton closeVariant={theme === "dark" ? "white" : undefined}>
          <Modal.Title>⚠️ Choose Import Option</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <p>How do you want to import the file?</p>
          <ul>
            <li><b>📌 Add</b>: Add to existing data</li>
            <li><b>🔄 Replace</b>: Clear all data and replace with file</li>
          </ul>
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowModal(false)}>Cancel</Button>
          <Button variant="success" onClick={() => processImport(false)}>📌 Add</Button>
          <Button variant="danger" onClick={() => processImport(true)}>🔄 Replace</Button>
        </Modal.Footer>
      </Modal>

      {/* -------- Result Modal -------- */}
      <Modal 
        show={resultModal.show} 
        onHide={() => setResultModal({ ...resultModal, show: false })} 
        centered
        contentClassName={theme === "dark" ? "bg-dark text-light" : ""}
      >
        <Modal.Header closeButton closeVariant={theme === "dark" ? "white" : undefined}>
          <Modal.Title>
            {resultModal.success ? "✅ Success" : "❌ Error"}
          </Modal.Title>
        </Modal.Header>
        <Modal.Body>{resultModal.message}</Modal.Body>
        <Modal.Footer>
          <Button 
            variant={theme === "dark" ? "light" : "primary"} 
            onClick={() => { 
              setResultModal({ ...resultModal, show: false }); 
              window.location.reload(); 
            }}
          >
            OK
          </Button>
        </Modal.Footer>
      </Modal>
    </div>
  );
}
