import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';
import reportWebVitals from './reportWebVitals';
import { BrowserRouter } from 'react-router-dom'
import 'bootstrap/dist/css/bootstrap.min.css'
import 'swiper/css'
import * as ServiceWorker from './serviceWorkerRegistration'
import { processQueue } from './db';

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(
<React.StrictMode>
  <BrowserRouter>
    <App />
  </BrowserRouter>
</React.StrictMode>,
);
ServiceWorker.register()
// If you want to start measuring performance in your app, pass a function
// to log results (for example: reportWebVitals(console.log))
// or send to an analytics endpoint. Learn more: https://bit.ly/CRA-vitals
reportWebVitals();


// Listen for coming back online and process sync queue
window.addEventListener('online', async () => {
  console.log('Network status: online — attempting to process sync queue');
  try {
    const res = await processQueue();
    console.log('Sync result:', res);
  } catch (e) {
    console.error('Error processing sync queue', e);
  }
});

// Optionally process queue at startup if online
if (navigator.onLine) {
  processQueue().then(res => console.log('Initial sync attempt:', res)).catch(err => console.warn(err));
}
