import { Modal, Button } from "react-bootstrap";

export default function NotFoundModal({ show, onClose, theme }) {
  return (
    <Modal show={show} onHide={onClose} centered>
      <Modal.Header
        closeButton
        className={theme === "light" ? "bg-light text-dark" : "bg-dark text-light"}
      >
        <Modal.Title>لغت پیدا نشد</Modal.Title>
      </Modal.Header>
      <Modal.Body className={theme === "light" ? "bg-light text-dark" : "bg-dark text-light"}>
        متأسفانه این لغت در دیکشنری موجود نیست.
      </Modal.Body>
      <Modal.Footer className={theme === "light" ? "bg-light text-dark" : "bg-dark text-light"}>
        <Button variant="secondary" onClick={onClose}>بستن</Button>
      </Modal.Footer>
    </Modal>
  );
}
