// PracticeToday.js
import React, { useEffect, useState , useRef } from "react";
import { Container, Button, Modal } from "react-bootstrap";
import { Swiper, SwiperSlide } from "swiper/react";
import { EffectCards } from "swiper/modules";
import "swiper/css";
import "swiper/css/effect-cards";
import { db, getCardsByDeck } from "../db";
import { useNavigate } from "react-router-dom";
import './PracticeToday.css'

export default function PracticeToday() {
  const navigate = useNavigate();
  const [cards, setCards] = useState([]);
  const [flipped, setFlipped] = useState({});
  const [currentIndex, setCurrentIndex] = useState(1);
  const today = new Date();
  const swiperRef = useRef(null);
  const [showMasteredModal, setShowMasteredModal] = useState(false);


   // 🔹 state برای Modal
  const [showHarderModal, setShowHarderModal] = useState(false);

  // فاصله‌های مرور به روز
  const intervals = {
    1: 1,
    2: 2,
    3: 4,
    4: 7,
    5: 14,
  };

  useEffect(() => {
    const loadCards = async () => {
      const allCards = await db.cards.toArray();

      const todaysCards = allCards.filter((card) => {
        if (!card.lastReviewed) return true; // اگر تا حالا مرور نشده
        const lastDate = new Date(card.lastReviewed);
        const intervalDays = intervals[card.level] || 1;
        const nextReview = new Date(
          lastDate.getFullYear(),
          lastDate.getMonth(),
          lastDate.getDate() + intervalDays
        );
        return nextReview <= today;
      });

      setCards(todaysCards);
    };
    loadCards();
  }, []);

  const toggleFlip = (cardId) => {
    setFlipped((prev) => ({
      ...prev,
      [cardId]: !prev[cardId],
    }));
  };

 const updateCardLevel = async (card, change) => {
  const newLevel = Math.min(6, Math.max(1, card.level + change));

  const updatedCard = {
    ...card,
    level: newLevel,
    lastReviewed: today.toISOString(),
    reviewCount: (card.reviewCount || 0) + 1,
  };

  await db.cards.put(updatedCard);

  setCards((prev) => {
    // 📌 شرط برای Harder وقتی کارت سطح 1 است
    if (change === -1 && card.level === 1) {
        setShowHarderModal(true); // 🔹 نمایش Modal
      return prev; // کارت در لیست باقی بمونه
    }
     if (newLevel === 6) {
      // کارت به سطح 6 رسید → Modal Mastered
      setShowMasteredModal(true);
      // کارت از مرور امروز حذف شود
      return prev.filter((c) => c.id !== card.id);
    }
    // در بقیه حالت‌ها کارت حذف بشه
    const newCards = prev.filter((c) => c.id !== card.id);
    setCurrentIndex((prevIndex) => Math.min(prevIndex, newCards.length));
    return newCards;
  });
};



  const speakWord = (word) => {
    const utterance = new SpeechSynthesisUtterance(word);
    utterance.lang = "en-US";
    speechSynthesis.speak(utterance);
  };

  return (
   

    <>

     <Container className="practice-page" style={{ minHeight: "100vh" }}>
      <div className="box-flashcard text-center">
        <div className="mb-4 text-start">
          <Button variant="primary" onClick={() => navigate("/")}>
            ⬅ Back to Home
          </Button>
        </div>

        <h2 className="mb-4">Today's Flashcards</h2>

        <p className="text-info mb-3">
          {currentIndex} of {cards.length}
        </p>

        {cards.length === 0 ? (
          <p>No flashcards to review today!</p>
        ) : (
          <Swiper
            effect={"cards"}
            grabCursor={true}
            loop={false}
            modules={[EffectCards]}
            className="mySwiper"
            onSlideChange={(swiper) =>
              setCurrentIndex(
                (swiper.realIndex + 1) % cards.length || cards.length
              )
            }
             key={cards.length} // 🔑 مهم برای رندر مجدد وقتی کارت حذف شد
          >
            {cards.map((card) => (
              <SwiperSlide key={card.id}>
                <div
                  className={`flashcard_p ${flipped[card.id] ? "flipped" : ""}`}
                >
                  <div className="flashcard-inner">
                    <div className="flashcard-front">
                      <h5>{card.word}</h5>
                      <p>{card.phonetic}</p>

                      <Button
                        variant="outline-light"
                        size="sm"
                        onClick={() => speakWord(card.word)}
                        className="flashcard-btn"
                      >
                        🎧 Listen
                      </Button>
                      

                      <Button
                        variant="success"
                        size="sm"
                        className="flashcard-btn mt-2"
                        onClick={() => updateCardLevel(card, 1)}
                      >
                        ⬇ Easier
                      </Button>

                      <Button
                        variant="danger"
                        size="sm"
                        className="flashcard-btn mt-2"
                        onClick={() => updateCardLevel(card, -1)}
                      >
                        ⬆ Harder

                      </Button>

                      <Button
                        variant="secondary"
                        size="sm"
                        className="flashcard-btn mt-2"
                        onClick={() => toggleFlip(card.id)}
                      >
                        Flip →
                      </Button>
                    </div>

                    <div className="flashcard-back">
                      {card.meaning_en && (
                        <p>
                          <strong>Meaning (EN):</strong> {card.meaning_en}
                        </p>
                      )}
                      {card.meaning_fa && (
                        <p>
                          <strong>Meaning (FA):</strong> {card.meaning_fa}
                        </p>
                      )}
                      {card.example && (
                        <p>
                          <strong>Example:</strong> {card.example}
                        </p>
                      )}
                      <p>
                        <strong>Level:</strong> {card.level}
                      </p>
                      <p>
                        <strong>Review Count:</strong> {card.reviewCount || 0}
                      </p>

                      <Button
                        variant="secondary"
                        size="sm"
                        className="flashcard-btn mt-2"
                        onClick={() => toggleFlip(card.id)}
                      >
                        ← Flip Back
                      </Button>
                    </div>
                  </div>
                </div>
              </SwiperSlide>
            ))}
          </Swiper>
        )}
      </div>
    </Container>

    <Modal
  show={showHarderModal}
  onHide={() => setShowHarderModal(false)}
  centered
  className="bg-dark text-light"
>
  <Modal.Header closeButton className="bg-dark text-light border-light">
    <Modal.Title>⚠️ Card at Minimum Level</Modal.Title>
  </Modal.Header>
  <Modal.Body className="bg-dark text-light">
    This card is already at the lowest level (Level 1). You cannot make it harder, but it will remain in your daily review list.
  </Modal.Body>
  <Modal.Footer className="bg-dark text-light border-light">
    <Button
      variant="light"
      onClick={() => setShowHarderModal(false)}
    >
      OK
    </Button>
  </Modal.Footer>
</Modal>

<Modal
  show={showMasteredModal}
  onHide={() => setShowMasteredModal(false)}
  centered
  className="bg-dark text-light"
>
  <Modal.Header closeButton className="bg-dark text-light border-light">
    <Modal.Title>🎉 Mastered!</Modal.Title>
  </Modal.Header>
  <Modal.Body className="bg-dark text-light">
    Congratulations! This word is now fully mastered. It will no longer appear in your daily review. 
    You can always change its level manually if needed.
  </Modal.Body>
  <Modal.Footer className="bg-dark text-light border-light">
    <Button
      variant="light"
      onClick={() => setShowMasteredModal(false)}
    >
      OK
    </Button>
  </Modal.Footer>
</Modal>


    
    </>
  );
}
