// HomePage.js
import React, { useState, useEffect, useRef } from "react";
import {
  Container,
  Navbar,
  Nav,
  Button,
  Card,
  ProgressBar,
  Row,
  Col,
  Modal,
  Form,
  FormControl,
} from "react-bootstrap";
import "bootstrap/dist/css/bootstrap.min.css";
import WordSearch from "../components/WordSearch"; // کامپوننت جستجوی کلمات
import { db, addDeck, getDecks, addCard } from "../db"; // Dexie DB
import { useNavigate } from "react-router-dom";
import { NavLink } from "react-router-dom";
import { Link } from "react-router-dom";
import NotFoundModal from "../components/modals/NotFoundModal";
import FlashCardModal from "../components/modals/FlashCardModal";
import ConfirmDeleteModal from "../components/modals/ConfirmDeleteModal";
import AddDeckModal from "../components/modals/AddDeckModal";
import ConfirmResetModal from "../components/modals/ConfirmResetModal";
import { BsQuestionCircle } from "react-icons/bs";
import { BsQuestionCircleFill } from "react-icons/bs"; // یا AiOutlineQuestionCircle
import SettingsModal from "../components/modals/SettingsModal";
// بالای کامپوننت HomePage
const intervals = { 1: 1, 2: 2, 3: 4, 4: 7, 5: 14 };
const today = new Date();

export default function HomePage() {
  const navigate = useNavigate();
  // ---------- States ----------
  const [decks, setDecks] = useState([]); // لیست دسته‌ها
  const [theme, setTheme] = useState("light"); // تم (Light/Dark)
  const [showModal, setShowModal] = useState(false); // Modal افزودن دسته
  const [newDeckName, setNewDeckName] = useState(""); // نام دسته جدید
  const inputRef = useRef(null); // ref برای فوکوس خودکار input
  const [showDeleteModal, setShowDeleteModal] = useState(false); // Modal تایید حذف
  const [deckToDelete, setDeckToDelete] = useState(null); // دسته‌ای که قرار است حذف شود
  const [showFlashCardModal, setShowFlashCardModal] = useState(false);
  const [currentWordData, setCurrentWordData] = useState(null);
  const [selectedDeckId, setSelectedDeckId] = useState("");
  const [newDeckForFlash, setNewDeckForFlash] = useState(""); // افزودن دسته جدید داخل FlashCard Modal
  const [showNotFoundModal, setShowNotFoundModal] = useState(false);
  const [stats, setStats] = useState({
    decks: 0,
    totalCards: 0,
  });
  const [todaysCount, setTodaysCount] = useState(0);
  const [showResetModal, setShowResetModal] = useState(false);
  const [showSettings, setShowSettings] = useState(false);

  const [undoTimeout, setUndoTimeout] = useState(null);
const [recentlyDeletedDeck, setRecentlyDeletedDeck] = useState(null);
const [showUndo, setShowUndo] = useState(false);


  // ---------- تم ----------
  const toggleTheme = () => {
    const newTheme = theme === "light" ? "dark" : "light";
    setTheme(newTheme);
    localStorage.setItem("flashcard-theme", newTheme); // ذخیره تم در localStorage
  };

  // ---------- بارگذاری تم از localStorage هنگام mount ----------
  useEffect(() => {
    const savedTheme = localStorage.getItem("flashcard-theme");
    if (savedTheme) {
      setTheme(savedTheme);
    }
  }, []);

  // ---------- Load decks from IndexedDB هنگام mount ----------
  useEffect(() => {
    refreshDecksAndStats(); // ← اینجا به جای getDecks().then(setDecks) استفاده کن
  }, []);

  // ---------- ریفرش Deckها و آمار ----------
  // ---------- ریفرش Deckها و آمار ----------
const refreshDecksAndStats = async () => {
  const updatedDecks = await getDecks();

  // محاسبه درصد پیشرفت هر Deck
  const decksWithProgress = await Promise.all(
    updatedDecks.map(async (deck) => {
      const progress = await calculateDeckProgress(deck);
      return { ...deck, progress };
    })
  );

  // 👇 این دو خط جدیدن
  const allCards = await db.cards.toArray();
  const overallProgress = calculateOverallProgressFromCards(allCards); // از فانکشنی که پایین ساختی استفاده کن

  // 👇 دک مجازی
  const virtualAllDeck = {
    id: "all",          // عمداً رشته تا با idهای عددی قاطی نشه
    name: "Total Cards",
    cards: allCards.length,
    progress: overallProgress,
    isVirtual: true,
  };

  // 👇 حالا ست کن (دک‌های واقعی + دک مجازی)
  setDecks([...decksWithProgress, virtualAllDeck]);

  // آمار واقعی (بدون دک مجازی)
  const totalCards = allCards.length;
  setStats({
    decks: updatedDecks.length,
    totalCards,
  });
};


  // ---------- Load today's flashcards count ----------
  useEffect(() => {
    const loadTodaysCards = async () => {
      const allCards = await db.cards.toArray();

      const todaysCards = allCards.filter((card) => {
        if (!card.lastReviewed) return true; // اگر تا حالا مرور نشده
        const lastDate = new Date(card.lastReviewed);
        const intervalDays = intervals[card.level] || 1;
        const nextReview = new Date(
          lastDate.getFullYear(),
          lastDate.getMonth(),
          lastDate.getDate() + intervalDays
        );
        return nextReview <= today;
      });

      setTodaysCount(todaysCards.length);
    };

    loadTodaysCards();
  }, [decks]); // هر بار که deckها تغییر کنند هم آپدیت شود

  

  useEffect(() => {
    const loadStats = async () => {
      const decksArray = await db.decks.toArray();
      const totalCards = await db.cards.count();
      setStats({
        decks: decksArray.length,
        totalCards,
      });
    };
    loadStats();
  }, [decks]);

  // ---------- افزودن دسته جدید ----------
  const handleAddDeck = async () => {
    if (newDeckName.trim() === "") return; // اگر خالی بود، کاری انجام نده
    const newDeck = { name: newDeckName, cards: 0, progress: 0 };
    await addDeck(newDeck); // اضافه کردن به IndexedDB
    const updatedDecks = await getDecks(); // گرفتن لیست به‌روز
    setDecks(updatedDecks); // آپدیت state
    setNewDeckName(""); // پاک کردن input
    setShowModal(false); // بستن modal
    window.location.reload()
  };

  // ---------- فوکوس خودکار روی input هنگام باز شدن modal ----------
  useEffect(() => {
    if (showModal) {
      setTimeout(() => inputRef.current?.focus(), 100); // کمی تاخیر برای render
    }
  }, [showModal]);

  // ---------- انتخاب کلمه از WordSearch ----------
  const handleSelectWord = async (word) => {
  console.log("Selected word:", word);

  let wordData = {
    word,
    phonetic: "",
    meaning_en: "",
    meaning_fa: "",
    example: "",
    synonyms: [],
    // image_url: `https://picsum.photos/400/300?random=${encodeURIComponent(word)}`,
    meanings: [],
  };

  try {
    const res = await fetch(`https://api.dictionaryapi.dev/api/v2/entries/en/${word}`);
    if (res.ok) {
      const data = await res.json();
      const phonetic = data[0].phonetic || "";
      const mainDefinition = data[0].meanings[0]?.definitions[0] || {};
      const meaning_en = mainDefinition.definition || "";
      const example = mainDefinition.example || "";
      const synonyms = mainDefinition.synonyms || [];

      // ترجمه به فارسی
      let meaning_fa = "";
      try {
        const translateRes = await fetch(
          `https://api.mymemory.translated.net/get?q=${encodeURIComponent(
            meaning_en
          )}&langpair=en|fa`
        );
        const translateData = await translateRes.json();
        meaning_fa = translateData.responseData.translatedText;
      } catch (err) {
        console.warn("Translation failed:", err);
      }

      wordData = { ...wordData, phonetic, meaning_en, meaning_fa, example, synonyms };
    }
  } catch (err) {
    console.warn("API fetch failed, using offline mode:", err);
  }

  // باز کردن Modal همیشه
  setCurrentWordData(wordData);
  setShowFlashCardModal(true);
  setSelectedDeckId(decks[0]?.id || "");
};


  // ---------- افزودن FlashCard به یک Deck ----------
  // const handleAddFlashCard = async () => {
  //   if (!selectedDeckId) return;
  //   if (!currentWordData) return;

  //   // فلش کارت را به Deck انتخاب شده اضافه کن
  //   const deck = await db.decks.get(selectedDeckId);
  //   if (!deck.cardsArray) deck.cardsArray = [];
  //   deck.cardsArray.push(currentWordData);
  //   deck.cards = deck.cardsArray.length;
  //   await db.decks.put(deck);

  //   // آپدیت لیست Deckها
  //   const updatedDecks = await getDecks();
  //   setDecks(updatedDecks);

  //   setShowFlashCardModal(false);
  //   setCurrentWordData(null);
  // };

  // ---------- افزودن دسته جدید از داخل FlashCard Modal ----------
  const handleAddDeckFromFlash = async () => {
    if (newDeckForFlash.trim() === "") return;
    const newDeck = {
      name: newDeckForFlash,
      cards: 0,
      progress: 0,
      cardsArray: [],
    };
    await addDeck(newDeck);
    const updatedDecks = await getDecks();
    setDecks(updatedDecks);
    setSelectedDeckId(updatedDecks[updatedDecks.length - 1].id); // انتخاب دسته جدید
    setNewDeckForFlash("");
  };

  const handleGoToDeck = (deck) => {
    // انتقال به صفحه DeckPage با نام دسته
    navigate(`/deck/${deck.id}`, { state: { deck } });
  };

  // ---------- تایید حذف ----------
  const confirmDeleteDeck = (deck) => {
    setDeckToDelete(deck); // تعیین دسته‌ای که حذف می‌شود
    setShowDeleteModal(true); // باز کردن modal
  };

  // ---------- حذف دسته ----------
  // ---------- حذف دسته ----------
  const deleteDeck = async () => {
    if (!deckToDelete) return;

    // 🗑 اول حذف همه کارت‌های داخل دسته
    await db.cards.where("deckId").equals(deckToDelete.id).delete();

    // 🗑 بعد حذف خود دسته
    await db.decks.delete(deckToDelete.id);

    // 🔄 آپدیت لیست deckها
    const updatedDecks = await getDecks();
    setDecks(updatedDecks);

    // 🔄 بروزرسانی آمار
    await refreshDecksAndStats();

    // پاک‌سازی state
    setDeckToDelete(null);
    setShowDeleteModal(false);
  };

  // ---------- مرور لغات ----------
  const handleTodayPractice = () => {
    // برای نمونه می‌تونیم alert بزنیم یا navigate به صفحه تمرین
    console.log("Navigating to today's flashcards...");

    // اگر از React Router استفاده می‌کنید:
    // navigate('/practice-today');
    navigate("/practiceToday");
  };

  // ---------- اضافه کردن کارت به دسته ----------

  const handleSaveFlashCard = async () => {
    if (!selectedDeckId || !currentWordData) return;

    const newCard = {
      // id: crypto.randomUUID(),
      deckId: parseInt(selectedDeckId),
      word: currentWordData.word,
      phonetic: currentWordData.phonetic,
      audio: currentWordData.audio || "",
      meaning_fa: currentWordData.meaning_fa,
      meaning_en: currentWordData.meaning_en,
      example: currentWordData.example,
      synonyms:currentWordData.synonyms,
      note: currentWordData.note || "",
      level: 1,
      createdAt: new Date().toISOString(),
      lastReviewed: null,
      reviewCount: 0,
    };

    // 1. ذخیره کارت جدید
    await db.cards.add(newCard);
    console.log(selectedDeckId, typeof selectedDeckId);

    // 2. آپدیت تعداد کارت‌های deck
    const deck = await db.decks.get(parseInt(selectedDeckId));
    if (deck) {
      deck.cards = (deck.cards || 0) + 1;
      await db.decks.put(deck);
    }

    // 3. ریفرش deckها
    const updatedDecks = await getDecks();
    setDecks(updatedDecks);

    await refreshDecksAndStats(); // ← اینجا اضافه کن

    // 4. بستن modal
    setShowFlashCardModal(false);
    setCurrentWordData(null);
  };

  // دکمه ریست دیتابیس
  const handleResetConfirm = async () => {
    await db.delete(); // دیتابیس رو پاک کن
    await db.open(); // دوباره باز کن
    window.location.reload(); // ری‌لود کن
  };

  const calculateDeckProgress = async (deck) => {
    const cards = await db.cards.where("deckId").equals(deck.id).toArray();
    if (cards.length === 0) return 0;

    const maxLevel = 5;
    const totalMax = cards.length * maxLevel;
    const totalLevel = cards.reduce((sum, card) => sum + (card.level || 1), 0);

    return Math.round((totalLevel / totalMax) * 100);
  };


  // بلاتن
  // زیرِ calculateDeckProgress این را اضافه کن
const calculateOverallProgressFromCards = (cards) => {
  if (!cards.length) return 0;
  const maxLevel = 5;
  const totalMax = cards.length * maxLevel;
  const totalLevel = cards.reduce((sum, c) => sum + (c.level || 1), 0);
  return Math.round((totalLevel / totalMax) * 100);
};


  return (
    <div
      className={
        theme === "light"
          ? "bg-light text-dark min-vh-100"
          : "bg-dark text-light min-vh-100"
      }
    >
      {/* ---------- Navbar ---------- */}
      <Navbar bg={theme} variant={theme} expand="lg" className="mb-4">
        <Container>
          <Navbar.Brand>FlashCards</Navbar.Brand>
          <Nav className="ms-auto d-flex align-items-center ">
            <Button
              variant={theme === "light" ? "dark" : "light"}
              onClick={toggleTheme}
              className="me-2"
            >
              {theme === "light" ? "🌙 Dark" : "☀️ Light"}
            </Button>

            
          </Nav>
        </Container>
      </Navbar>

      <Container>
        {/* ---------- WordSearch ---------- */}
        <WordSearch onSelectWord={handleSelectWord} theme={theme} />

     

        {/* ---------- Add New Deck ---------- */}
        <div className="d-flex flex-column flex-md-row mb-5 gap-2">
          <Button variant="primary" onClick={() => setShowModal(true)}>
            ➕ Add New Deck
          </Button>
          <Button variant="info" onClick={handleTodayPractice}>
            📝 Today’s Flashcards ({todaysCount})
          </Button>

          <Button variant="secondary" onClick={() => setShowSettings(true)}>
  ⚙️ Settings
</Button>

        
        </div>

        {/* ---------- Deck List ---------- */}
       <Row xs={1} md={2} lg={3} className="g-4 mb-4">
  {decks.map((deck) => (
    <Col key={deck.id}>
      <Card
        className="h-100 shadow-lg"
        style={{
          cursor: "pointer",
          borderRadius: "15px",
          border: "none",
          padding: "0",
          background: theme === "light"
            ? "linear-gradient(135deg, #e0f7fa, #b2ebf2)"
            : "linear-gradient(135deg, #333333, #1a1a1a)",
          boxShadow: theme === "light"
            ? "0 8px 20px rgba(0, 0, 0, 0.15)"
            : "0 8px 20px rgba(0, 0, 0, 0.6)",
        }}
      >
        <Card.Body className="d-flex flex-column p-3">
          <div className="d-flex justify-content-between align-items-start mb-3">
            <div>
              <Card.Title className="mb-1" style={{ color: theme === "light" ? "#555" : "#eee" , fontWeight: "bold" }}>
                {deck.name}
              </Card.Title>
              <small style={{ color: theme === "light" ? "#555" : "#ccc" }}>
                {deck.cards} cards
              </small>
            </div>

           {!deck.isVirtual && (
  <Button
    variant="danger"
    size="sm"
    onClick={() => confirmDeleteDeck(deck)}
  >
    🗑
  </Button>
)}
          </div>

          {/* نوار پیشرفت */}
          <ProgressBar
            now={deck.progress}
            style={{
              height: "25px",
              borderRadius: "12px",
              overflow: "hidden",
              boxShadow: "0 2px 6px rgba(0,0,0,0.2)",
              transition: "all 0.6s ease",
            }}
            className="mb-3"
            animated
            variant="info"
            label={
              <span
                style={{
                  color: theme === "light" ? "#fff" : "#000",
                  fontWeight: "bold",
                }}
              >
                {deck.progress}%
              </span>
            }
          />

          <Button
            variant={theme === "light" ? "success" : "success"}
            size="sm"
            className="mt-auto"
            onClick={() => handleGoToDeck(deck)}
          >
            Go →
          </Button>
        </Card.Body>
      </Card>
    </Col>
  ))}
</Row>


        {/* ---------- Stats ---------- */}
      <Card
  className={`p-4  shadow-lg ${theme === "light" ? "bg-white text-dark" : "bg-dark text-light"}`}
  style={{
    borderRadius: "15px",
    border: "none",
    background: theme === "light" 
      ? "linear-gradient(135deg, #f0f8ff, #d1e7ff)" 
      : "linear-gradient(135deg, #2c2c2c, #1a1a1a)",
    boxShadow: theme === "light"
      ? "0 4px 20px rgba(0, 0, 0, 0.1)"
      : "0 4px 20px rgba(0, 0, 0, 0.5)"
  }}
>
  <h5 style={{ fontWeight: "bold", marginBottom: "8px" }}>📊 Stats</h5>
  <p style={{ margin: 0, fontSize: "16px" }}>
    <span style={{ fontWeight: "bold" }}>{stats.decks}</span> decks |{" "}
    <span style={{ fontWeight: "bold" }}>{stats.totalCards}</span> total cards
  </p>
</Card>

      </Container>

      {/* ---------- Modal افزودن دسته ---------- */}
      <AddDeckModal
        show={showModal}
        onClose={() => setShowModal(false)}
        onSave={handleAddDeck}
        theme={theme}
        inputRef={inputRef}
        newDeckName={newDeckName}
        setNewDeckName={setNewDeckName}
      />

      <ConfirmDeleteModal
        show={showDeleteModal}
        onClose={() => setShowDeleteModal(false)}
        onConfirm={deleteDeck}
        theme={theme}
        deckToDelete={deckToDelete}
      />

      <FlashCardModal
        show={showFlashCardModal}
        onClose={() => setShowFlashCardModal(false)}
        onSave={handleSaveFlashCard}
        theme={theme}
        currentWordData={currentWordData}
        setCurrentWordData={setCurrentWordData}
        decks={decks}
        selectedDeckId={selectedDeckId}
        setSelectedDeckId={setSelectedDeckId}
        newDeckForFlash={newDeckForFlash}
        setNewDeckForFlash={setNewDeckForFlash}
        handleAddDeckFromFlash={handleAddDeckFromFlash}
      />

      {/* ---------- Modal لغت پیدا نشد ---------- */}
      <NotFoundModal
        show={showNotFoundModal}
        onClose={() => setShowNotFoundModal(false)}
        theme={theme}
      />

     <SettingsModal
  show={showSettings}
  onClose={() => setShowSettings(false)}
  setDecks={setDecks}
  theme={theme}
  onShowReset={() => setShowResetModal(true)}
/>

<ConfirmResetModal
  show={showResetModal}
  onClose={() => setShowResetModal(false)}
  onConfirm={handleResetConfirm}
  theme={theme}
/>

    </div>
  );
}
