import { Modal, Button } from "react-bootstrap";
import { BsQuestionCircleFill } from "react-icons/bs";
import { Link } from "react-router-dom";
import BackupControls from "../BackupControls";
function SettingsModal({ show, onClose, setDecks, theme, onShowReset }) {
  return (
    <Modal show={show} onHide={onClose} centered>
      <Modal.Header closeButton className={theme === "light" ? "" : "bg-dark text-light"}>
        <Modal.Title>Settings</Modal.Title>
      </Modal.Header>
      <Modal.Body className={theme === "light" ? "" : "bg-dark text-light"}>
        {/* Reset Database */}
        <Button 
          variant="danger" 
          className="w-100 mb-3" 
          onClick={onShowReset} // فقط مدال تأیید رو باز می‌کنه
        >
          🗑 Reset Database
        </Button>

        {/* Backup Controls */}
        <BackupControls setDecks={setDecks} theme={theme} />

        {/* Help Link */}
        <Link 
          to="/help" 
          className="btn btn-info w-100 mt-3 d-flex align-items-center justify-content-center"
        >
          <BsQuestionCircleFill size={20} className="me-2" /> Help
        </Link>
      </Modal.Body>
    </Modal>
  );
}



export default SettingsModal;
